import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyThongBao = () => {
    const [tabActive, setTabActive] = useState('view');
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');

    // Khởi tạo state từ localStorage (nếu có) hoặc mảng rỗng
    const [notifications, setNotifications] = useState(() => {
        const savedNotis = localStorage.getItem('building_notifications');
        return savedNotis ? JSON.parse(savedNotis) : [
            {
                id: 1,
                title: "Thông báo hệ thống",
                body: "Chào mừng bạn đến với bảng tin tòa nhà.",
                date: "22/04/2026",
                sender: "AD"
            }
        ];
    });

    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [notiToDelete, setNotiToDelete] = useState(null);

    // Mỗi khi danh sách notifications thay đổi, tự động lưu vào localStorage
    useEffect(() => {
        localStorage.setItem('building_notifications', JSON.stringify(notifications));
    }, [notifications]);

    const handleSendNotification = () => {
        if (!title.trim() || !content.trim()) return;

        const newNoti = {
            id: Date.now(),
            title: title,
            body: content,
            date: new Date().toLocaleDateString('vi-VN'),
            sender: "AD"
        };

        setNotifications([newNoti, ...notifications]);
        setTitle('');
        setContent('');
        setTabActive('view');
    };

    const openConfirm = (id) => {
        setNotiToDelete(id);
        setShowDeleteConfirm(true);
    };

    const confirmDelete = () => {
        const updatedNotis = notifications.filter(n => n.id !== notiToDelete);
        setNotifications(updatedNotis);
        setShowDeleteConfirm(false);
        setNotiToDelete(null);
    };

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', position: 'relative'
        }} className="glass-card">

            {/* Modal xác nhận xóa */}
            {showDeleteConfirm && (
                <div style={{
                    position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
                    backgroundColor: 'rgba(0,0,0,0.6)', display: 'flex', 
                    alignItems: 'center', justifyContent: 'center', zIndex: 1000,
                    backdropFilter: 'blur(5px)'
                }}>
                    <div style={{
                        backgroundColor: '#fff', padding: '30px', borderRadius: '20px',
                        textAlign: 'center', width: '300px', boxShadow: '0 10px 25px rgba(0,0,0,0.2)'
                    }}>
                        <p style={{ fontWeight: 'bold', marginBottom: '20px', color: '#333' }}>Xác nhận xóa thông báo này?</p>
                        <div style={{ display: 'flex', gap: '10px', justifyContent: 'center' }}>
                            <button 
                                onClick={confirmDelete}
                                style={{ padding: '10px 25px', borderRadius: '10px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', cursor: 'pointer', fontWeight: 'bold' }}
                            >Xác nhận</button>
                            <button 
                                onClick={() => setShowDeleteConfirm(false)}
                                style={{ padding: '10px 25px', borderRadius: '10px', border: '1px solid #ddd', backgroundColor: '#fff', color: '#666', cursor: 'pointer' }}
                            >Hủy</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Thanh Tab */}
            <div style={{ padding: '20px', display: 'flex', gap: '15px' }}>
                <button 
                    onClick={() => setTabActive('view')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'view' ? '#333' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'view' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >Khung thông báo</button>
                <button 
                    onClick={() => setTabActive('send')}
                    style={{
                        padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold',
                        backgroundColor: tabActive === 'send' ? '#8b5e5e' : 'rgba(255,255,255,0.6)',
                        color: tabActive === 'send' ? '#fff' : '#333', cursor: 'pointer', transition: '0.3s'
                    }}
                >Gửi thông báo</button>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', overflow: 'hidden' }}>
                {tabActive === 'view' ? (
                    <div style={{ height: '100%', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px', paddingRight: '10px' }}>
                        {notifications.length > 0 ? notifications.map(noti => (
                            <div key={noti.id} style={{
                                backgroundColor: 'rgba(255,255,255,0.9)', padding: '20px', 
                                borderRadius: '20px', position: 'relative', boxShadow: '0 4px 6px rgba(0,0,0,0.05)'
                            }}>
                                <div 
                                    onClick={() => openConfirm(noti.id)}
                                    style={{
                                        position: 'absolute', top: '15px', right: '20px',
                                        cursor: 'pointer', color: '#ccc', fontSize: '18px', 
                                        transition: '0.2s'
                                    }}
                                    onMouseOver={(e) => e.target.style.color = '#8b5e5e'}
                                    onMouseOut={(e) => e.target.style.color = '#ccc'}
                                >✕</div>

                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px', marginRight: '30px' }}>
                                    <span style={{ fontWeight: 'bold', color: '#8b5e5e', fontSize: '16px' }}>{noti.title}</span>
                                    <span style={{ fontSize: '12px', color: '#999' }}>{noti.date}</span>
                                </div>
                                <p style={{ margin: 0, fontSize: '14px', color: '#333', lineHeight: '1.5', whiteSpace: 'pre-wrap' }}>{noti.body}</p>
                            </div>
                        )) : (
                            <div style={{ textAlign: 'center', color: '#fff', marginTop: '50px', opacity: 0.8 }}>Chưa có thông báo nào.</div>
                        )}
                    </div>
                ) : (
                    <div style={{ 
                        backgroundColor: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(10px)',
                        borderRadius: '25px', padding: '30px', display: 'flex', flexDirection: 'column', gap: '20px' 
                    }}>
                        <input 
                            style={{ width: '100%', padding: '15px', borderRadius: '12px', border: 'none', outline: 'none' }}
                            placeholder="Tiêu đề thông báo..."
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                        />
                        <textarea 
                            style={{ width: '100%', height: '180px', padding: '15px', borderRadius: '12px', border: 'none', outline: 'none', resize: 'none', fontFamily: 'inherit' }}
                            placeholder="Nội dung thông báo..."
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                        />
                        <button 
                            onClick={handleSendNotification}
                            disabled={!title.trim() || !content.trim()}
                            style={{ 
                                alignSelf: 'flex-end', padding: '12px 40px', borderRadius: '12px', 
                                border: 'none', backgroundColor: '#8b5e5e', color: '#fff', 
                                fontWeight: 'bold', cursor: 'pointer', opacity: (title.trim() && content.trim()) ? 1 : 0.5
                            }}
                        >Gửi ngay</button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default QuanLyThongBao;
